he MIME type of this resource, if known.","type":"string"},"name":{"description":"A human-readable name for this resource.\n\nThis can be used by clients to populate UI elements.","type":"string"},"size":{"description":"The size of the raw resource content, in bytes (i.e., before base64 encoding or any tokenization), if known.\n\nThis can be used by Hosts to display file sizes and estimate context window usage.","type":"integer"},"uri":{"description":"The URI of this resource.","format":"uri","type":"string"}},"required":["name","uri"],"type":"object"},"Annotations":{"description":"Optional annotations for the client. The client can use annotations to inform how objects are used or displayed","properties":{"audience":{"description":"Describes who the intended customer of this object or data is.\n\nIt can include multiple entries to indicate content useful for multiple audiences (e.g., `[\"user\", \"assistant\"]`).","items":{"$ref":"#/definitions/Role"},"type":"array"},"priority":{"description":"Describes how important this data is for operating the server.\n\nA value of 1 means \"most important,\" and indicates that the data is\neffectively required, while 0 means \"least important,\" and indicates that\nthe data is entirely optional.","maximum":1,"minimum":0,"type":"number"}},"type":"object"},"Role":{"description":"The sender or recipient of messages and data in a conversation.","enum":["assistant","user"],"type":"string"},"SecurityScheme":{"anyOf":[{"$ref":"#/definitions/APIKeySecurityScheme"},{"$ref":"#/definitions/HTTPAuthSecurityScheme"},{"$ref":"#/definitions/OAuth2SecurityScheme"},{"$ref":"#/definitions/OpenIdConnectSecurityScheme"}],"description":"Mirrors the OpenAPI Security Scheme Object\n(https://swagger.io/specification/#security-scheme-object)"},"APIKeySecurityScheme":{"description":"API Key security scheme.","properties":{"description":{"description":"Description of this security scheme.","type":"string"},"in":{"description":"The location of the API ke