ons/ImplicitOAuthFlow","description":"Configuration for the OAuth Implicit flow"},"password":{"$ref":"#/definitions/PasswordOAuthFlow","description":"Configuration for the OAuth Resource Owner Password flow"}},"type":"object"},"AuthorizationCodeOAuthFlow":{"description":"Configuration details for a supported OAuth Flow","properties":{"authorizationUrl":{"description":"The authorization URL to be used for this flow. This MUST be in the form of a URL. The OAuth2\nstandard requires the use of TLS","type":"string"},"refreshUrl":{"description":"The URL to be used for obtaining refresh tokens. This MUST be in the form of a URL. The OAuth2\nstandard requires the use of TLS.","type":"string"},"scopes":{"additionalProperties":{"type":"string"},"description":"The available scopes for the OAuth2 security scheme. A map between the scope name and a short\ndescription for it. The map MAY be empty.","type":"object"},"tokenUrl":{"description":"The token URL to be used for this flow. This MUST be in the form of a URL. The OAuth2 standard\nrequires the use of TLS.","type":"string"}},"required":["authorizationUrl","scopes","tokenUrl"],"type":"object"},"ClientCredentialsOAuthFlow":{"description":"Configuration details for a supported OAuth Flow","properties":{"refreshUrl":{"description":"The URL to be used for obtaining refresh tokens. This MUST be in the form of a URL. The OAuth2\nstandard requires the use of TLS.","type":"string"},"scopes":{"additionalProperties":{"type":"string"},"description":"The available scopes for the OAuth2 security scheme. A map between the scope name and a short\ndescription for it. The map MAY be empty.","type":"object"},"tokenUrl":{"description":"The token URL to be used for this flow. This MUST be in the form of a URL. The OAuth2 standard\nrequires the use of TLS.","type":"string"}},"required":["scopes","tokenUrl"],"type":"object"},"ImplicitOAuthFlow":{"description":"Configuration details for a supported OAuth Flow","properties":{"authorizationUrl":{"desc